SELECT
  (SELECT COUNT(DISTINCT p.patient) FROM patients p JOIN conditions c ON c.PATIENT = p.patient WHERE p.gender = 'M' AND c.DESCRIPTION = 'Hypertension') AS male_count,
  (SELECT COUNT(DISTINCT p.patient) FROM patients p JOIN conditions c ON c.PATIENT = p.patient WHERE p.gender = 'F' AND c.DESCRIPTION = 'Hypertension') AS female_count;

SELECT (strftime('%Y', MIN(e.DATE)) - strftime('%Y', p.birthdate)) AS age
FROM patients p JOIN encounters e ON e.PATIENT = p.patient
WHERE p.first = 'Laronda' AND p.last = 'Bernier';

SELECT SUM(od.quantityOrdered) AS total_sold
FROM orderdetails od
WHERE od.productCode = (
  SELECT productCode FROM products ORDER BY (MSRP - buyPrice) DESC LIMIT 1
);

SELECT 100.0 * SUM(CASE WHEN julianday(requiredDate) - julianday(shippedDate) > 3 THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM orders
WHERE status = 'Shipped';

SELECT e.firstName, e.lastName, o.officeCode
FROM employees e JOIN offices o ON e.officeCode = o.officeCode
WHERE e.jobTitle = 'Sale Manager (EMEA)' AND o.territory = 'EMEA';

SELECT CAST(SUM(month) AS REAL) / COUNT(*) AS avg_duration
FROM longest_absense_from_school
WHERE name NOT IN (SELECT name FROM male);

SELECT MAX(c.year - CAST(m.lastNHL AS INTEGER)) AS years
FROM Coaches c JOIN Master m ON c.coachID = m.coachID
WHERE m.lastName = 'Waddell' AND c.lgID = 'NHL';

SELECT ac.award
FROM AwardsCoaches ac
WHERE ac.coachID = (
  SELECT coachID FROM Coaches WHERE lgID='NHL' GROUP BY coachID ORDER BY SUM(w) DESC LIMIT 1
) AND ac.lgID='NHL'
GROUP BY ac.award ORDER BY COUNT(*) DESC LIMIT 1;

SELECT m.firstName || ' ' || m.lastName AS full_name
FROM Goalies g JOIN Master m ON m.playerID = g.playerID
WHERE g.year = 1973 AND g.tmID = 'QUN' AND g.GP = '32';
